CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', district text NOT NULL DEFAULT '', avatar_path text, language text NOT NULL DEFAULT 'English', notifications_enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own profile" ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY "Create own profile" ON public.profiles FOR INSERT TO authenticated WITH CHECK (id=auth.uid());
CREATE POLICY "Update own profile" ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role text NOT NULL DEFAULT 'farmer' CHECK (role IN ('farmer','sacco_member','sacco_admin','admin')), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own roles" ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.farm360_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name,phone,district) VALUES (NEW.id,COALESCE(NEW.raw_user_meta_data->>'full_name',''),COALESCE(NEW.raw_user_meta_data->>'phone',''),COALESCE(NEW.raw_user_meta_data->>'district','')); INSERT INTO public.user_roles(user_id,role) VALUES (NEW.id,'farmer'); RETURN NEW; END; $$;
CREATE TRIGGER farm360_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.farm360_new_user();
INSERT INTO public.profiles(id) SELECT id FROM auth.users ON CONFLICT DO NOTHING;
INSERT INTO public.user_roles(user_id,role) SELECT id,'farmer' FROM auth.users ON CONFLICT DO NOTHING;
CREATE TABLE public.farms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES public.profiles(id),name text NOT NULL CHECK(length(trim(name))>0),district text NOT NULL DEFAULT '',village text NOT NULL DEFAULT '',size_acres numeric NOT NULL DEFAULT 0 CHECK(size_acres>=0),soil_type text NOT NULL DEFAULT '',water_source text NOT NULL DEFAULT '',farm_type text NOT NULL DEFAULT 'Mixed farming',archived boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.farms TO authenticated;
GRANT ALL ON public.farms TO service_role;
ALTER TABLE public.farms ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner reads farms" ON public.farms FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE POLICY "Owner creates farms" ON public.farms FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid());
CREATE POLICY "Owner updates farms" ON public.farms FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE POLICY "Owner deletes farms" ON public.farms FOR DELETE TO authenticated USING(owner_id=auth.uid());
CREATE INDEX farms_owner ON public.farms(owner_id);
CREATE TABLE public.fields (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),farm_id uuid NOT NULL REFERENCES public.farms(id),name text NOT NULL CHECK(length(trim(name))>0),size_acres numeric NOT NULL DEFAULT 0 CHECK(size_acres>=0),soil_type text NOT NULL DEFAULT '',irrigation text NOT NULL DEFAULT 'Rain-fed',archived boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.fields TO authenticated;
GRANT ALL ON public.fields TO service_role;
ALTER TABLE public.fields ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner manages fields" ON public.fields FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.farms WHERE id=farm_id AND owner_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.farms WHERE id=farm_id AND owner_id=auth.uid()));
CREATE INDEX fields_farm ON public.fields(farm_id);
CREATE TABLE public.role_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),requested_role text NOT NULL CHECK(requested_role IN ('sacco_member','sacco_admin','admin')),status text NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Approved','Rejected')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,requested_role));
GRANT SELECT,INSERT ON public.role_requests TO authenticated;
GRANT ALL ON public.role_requests TO service_role;
ALTER TABLE public.role_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own requests" ON public.role_requests FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY "Request only pending role" ON public.role_requests FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='Pending');